/** A corrective or preventive action of the hospital's register (MSDS IMS 162, CQI 83, 107). */
export interface QualityActionOut {
  action_id: number;
  action_number: string;
  /** What found the need: a medical record review, an incident, a complaint, an infection control audit, a committee meeting, a mock drill, a mock PHC interview, a QA round, a patient's feedback */
  source: "RecordReview" | "Incident" | "Complaint" | "InfectionAudit" | "Meeting" | "Drill" | "MockInterview" | "QaRound" | "PatientFeedback";
  cycle_id: number | null;
  cycle_number: string | null;
  incident_id: number | null;
  incident_number: string | null;
  complaint_id: number | null;
  complaint_number: string | null;
  ipc_audit_id: number | null;
  audit_number: string | null;
  meeting_id: number | null;
  meeting_number: string | null;
  drill_id: number | null;
  drill_number: string | null;
  mock_interview_id: number | null;
  /** The mock PHC interview that found the gap (MIV-...) */
  interview_number: string | null;
  qa_round_id: number | null;
  /** The in-charge's QA round whose finding it addresses (QAR-...) */
  qa_round_number: string | null;
  feedback_id: number | null;
  /** The patient feedback it answers (FB-...) */
  feedback_number: string | null;
  /** The number of the review cycle, the incident, the complaint, the audit or the meeting */
  source_number: string;
  action_type: "Corrective" | "Preventive";
  description: string;
  /** A record review: the checklist item whose deficiencies it addresses */
  criterion_code: string | null;
  department_id: number | null;
  department_name: string | null;
  owner_user_id: number;
  owner_name: string;
  due_date: string;
  status: "Open" | "Done" | "Cancelled";
  /** Done: what was done (the evidence); Cancelled: why it was dropped */
  outcome_note: string | null;
  completed_at: string | null;
  completed_by_name: string | null;
  created_by: number;
  created_by_name: string;
  created_at: string;
  row_version: number;
  is_overdue: boolean;
}

/** Any fields; the draft is saved as it is written. */
export interface MinutesIn {
  held_on?: string | null;
  venue?: string | null;
  agenda?: string | null;
  attendees?: MemberIn[] | null;
  apologies?: string | null;
  /** The issues discussed (MSDS CQI 94 i a) */
  issues?: string | null;
  /** The quality activities reviewed (CQI 94 i b): the indicators, the incidents, the audits */
  activities?: string | null;
  /** The decisions and recommendations (CQI 94 i c) */
  outcomes?: string | null;
  expected_version?: number | null;
}

/** A corrective or preventive action for its source (a record review, an incident). */
export interface QualityActionIn {
  action_type: "Corrective" | "Preventive";
  description: string;
  /** Who carries it out; they are notified and close it with the evidence (GET /staff/lookup → user_id; GET /quality/record-review/people, GET /facility/staff) */
  owner_user_id: number;
  due_date: string;
  /** The department (GET /admin/departments) */
  department_id?: number | null;
}

